async def send_heartbeat(job: JobInfo, interval: int = 15) -> None:
    """Send a heartbeat event every `interval` seconds while running."""
    try:
        while True:
            await asyncio.sleep(interval)
            await push_job_status_event(job, JobStatus.heartbeat)
    except asyncio.CancelledError:
        structlogger.debug("send_heartbeat.cancelled", job_id=job.id)
        raise


@observe(
    capture_input=False,
    capture_output=False,
)
async def run_prompt_to_bot_job(
    app: Any,
    project_generator: ProjectGenerator,
    job: JobInfo,
    prompt: str,
    user_id: Optional[str] = None,
) -> None:
    """Run the prompt-to-bot job in the background.

    Args:
        app: The Sanic application instance.
        project_generator: Generator of the agent's project the job operates on.
        job: The job information instance.
        prompt: The natural language prompt for bot generation.
        user_id: The user ID for the trace.
    """
    PromptToBotLangfuseTelemetry.setup_prompt_to_bot_trace(
        prompt=prompt,
        user_id=user_id,
        job_id=job.id,
    )

    copilot_template_prompt_job = job_manager.create_job()
    heartbeat_task = asyncio.create_task(send_heartbeat(job))

    try:
        # 0. Persist initial user prompt
        app.add_task(
            run_copilot_template_prompt_job(
                app, copilot_template_prompt_job, custom_prompt=prompt
            )
        )
        await push_job_status_event(
            job,
            JobStatus.received,
            payload={"copilot_template_prompt_job_id": copilot_template_prompt_job.id},
        )

        # 1. Generating
        await push_job_status_event(job, JobStatus.generating)
        (
            attempts,
            commit_sha,
        ) = await project_generator.generate_project_with_retries(
            prompt,
            template=ProjectTemplateName.BASIC,
        )
        bot_files = project_generator.get_bot_files()
        await push_job_status_event(job, JobStatus.generation_success)

        # Persist prompt to history after generation
        # This ensures the project directory and .rasa folder exist
        try:
            if prompt:
                await persist_user_message_to_thread(prompt)
        except Exception as persist_exc:
            # Don't fail the job if persistence fails, just log it
            structlogger.error(
                "prompt_to_bot_job.persist_prompt_failed",
                job_id=job.id,
                prompt=prompt,
                error=str(persist_exc),
            )

        # 2. Create copilot welcome message job
        copilot_welcome_job = job_manager.create_job(commit_sha)
        app.add_task(
            run_copilot_welcome_message_job(app, project_generator, copilot_welcome_job)
        )

        structlogger.info(
            "bot_builder_service.prompt_to_bot.success",
            files_generated=list(bot_files.keys()),
            copilot_welcome_job_id=copilot_welcome_job.id,
        )
        await push_job_status_event(
            job=job,
            status=JobStatus.done,
            payload={"copilot_welcome_job_id": copilot_welcome_job.id},
        )
        job_manager.mark_done(job)

        PromptToBotLangfuseTelemetry.update_prompt_to_bot_trace_output_success(
            bot_files=bot_files,
            attempts=attempts,
            max_attempts=config.PROJECT_GENERATION_MAX_RETRIES,
        )

    except ValidationError as exc:
        # Log levels to include in the error message
        log_levels = ["error"]
        if config.VALIDATION_FAIL_ON_WARNINGS:
            log_levels.append("warning")

        structlogger.debug(
            "prompt_to_bot_job.validation_error",
            job_id=job.id,
            error=str(exc),
            all_validation_logs=exc.validation_logs,
            included_log_levels=log_levels,
        )

        error_message = exc.get_error_message_with_logs(log_levels=log_levels)
        await push_job_status_event(
            job, JobStatus.validation_error, message=error_message
        )
        job_manager.mark_done(job, error=error_message)

        PromptToBotLangfuseTelemetry.update_prompt_to_bot_trace_output_failure(
            error=exc,
            attempts=config.PROJECT_GENERATION_MAX_RETRIES,
            max_attempts=config.PROJECT_GENERATION_MAX_RETRIES,
        )

    except (ProjectGenerationError, LLMGenerationError) as exc:
        structlogger.debug(
            "prompt_to_bot_job.generation_error", job_id=job.id, error=str(exc)
        )
        await push_job_status_event(job, JobStatus.generation_error, message=str(exc))
        job_manager.mark_done(job, error=str(exc))

        PromptToBotLangfuseTelemetry.update_prompt_to_bot_trace_output_failure(
            error=exc,
            attempts=config.PROJECT_GENERATION_MAX_RETRIES,
            max_attempts=config.PROJECT_GENERATION_MAX_RETRIES,
        )

    except Exception as exc:
        # Capture full traceback
        structlogger.exception(
            "prompt_to_bot_job.unexpected_error", job_id=job.id, error=str(exc)
        )
        await push_job_status_event(job, JobStatus.error, message=str(exc))
        job_manager.mark_done(job, error=str(exc))

        PromptToBotLangfuseTelemetry.update_prompt_to_bot_trace_output_failure(
            error=exc,
            attempts=config.PROJECT_GENERATION_MAX_RETRIES,
            max_attempts=config.PROJECT_GENERATION_MAX_RETRIES,
        )
    finally:
        heartbeat_task.cancel()
        try:
            await heartbeat_task
        except asyncio.CancelledError:
            pass
        except Exception as exc:
            structlogger.warning(
                "prompt_to_bot_job.heartbeat_task_failed",
                job_id=job.id,
                error=str(exc),
            )


def _get_agent_plan_store_for_app(app: Any) -> "SQLitePlanStore":
    """Return the per-app agent plan store, creating it on first use.

    Mirrors ``service._get_agent_plan_store`` but keys off the ``Sanic`` app
    directly, since a background job has no ``Request`` to read ``app`` from.
    """
    from rasa.builder.agent_plan.store import open_agent_plan_store

    store = getattr(app.ctx, "agent_plan_store", None)
    if store is None:
        store = open_agent_plan_store()
        app.ctx.agent_plan_store = store
    return store


def _build_plan_summary_message(plan: "AgentBuildPlan") -> str:
    """Build a plain-text copilot chat summary of a completed plan build.

    Args:
        plan: The approved plan that was just built into a Mantle agent.

    Returns:
        A plain-text message (no markdown) describing what was built, for
        display in the copilot chat history.
    """
    lines = [f'I built "{plan.name}" from your approved plan.']
    for skill in plan.skills:
        lines.append(f"- {skill.id}: {skill.description}")
    if plan.assumptions:
        assumptions_text = "; ".join(plan.assumptions)
        lines.append(f"Assumptions I made: {assumptions_text}.")
    lines.append("Try it in the chat on the left, and ask me here if you want changes.")
    return "\n".join(lines)


@observe(
    capture_input=False,
    capture_output=False,
)
async def run_plan_to_bot_job(
    app: Any,
    project_generator: ProjectGenerator,
    plan_id: str,
    revision: int,
    thread_id: Optional[str] = None,
) -> None:
    """Build a new Mantle agent from an approved agent build plan.

    Modeled on `run_prompt_to_bot_job`, but the "generation" step is
    deterministic (scaffold from template, then a task-specific pydantic-ai
    agent implements the approved plan) rather than an LLM structured-output
    call. The build stops at validation: the builder never trains or loads an
    agent, since Studio trains the project files in its own model service.
    A build that passes validation is committed, so branches made from `main`
    start from the built agent. On success, the original prompt and a
    plain-text summary of the build are persisted to the copilot v2 thread,
    best-effort.

    Args:
        app: The Sanic application instance.
        project_generator: Generator of the agent's project the plan is built
            into.
        plan_id: Id of the plan record to build. The plan's `job_id` (set by
            the approve route before this job was scheduled) is used to look
            up the `JobInfo` to push status events to.
        revision: The plan revision the caller approved. The build uses this
            revision's plan even if a newer revision has since been added, so
            the build stays pinned to what the user actually approved.
        thread_id: The v2 copilot thread id to persist the prompt and build
            summary to, supplied by the frontend on approve. `None` when the
            caller has no thread id, in which case the usual
            `HELLO_RASA_PROJECT_ID`-derived thread id is used instead.
    """
    from rasa.builder.agent_plan.builder import build_from_plan
    from rasa.builder.agent_plan.models import PlanStatus

    store = _get_agent_plan_store_for_app(app)
    record = await store.get_plan(plan_id)
    if record is None or record.job_id is None:
        structlogger.error("plan_to_bot_job.plan_or_job_missing", plan_id=plan_id)
        return

    approved_revision = await store.get_revision(plan_id, revision)
    if approved_revision is None:
        structlogger.error(
            "plan_to_bot_job.revision_missing",
            plan_id=plan_id,
            revision=revision,
        )
        return

    job = job_manager.get_job(record.job_id)
    if job is None:
        structlogger.error(
            "plan_to_bot_job.job_not_found", plan_id=plan_id, job_id=record.job_id
        )
        return

    heartbeat_task = asyncio.create_task(send_heartbeat(job))

    try:
        await store.set_status(plan_id, PlanStatus.BUILDING)
        await push_job_status_event(job, JobStatus.received)

        # 1. Scaffold the project from the same template prompt-to-bot uses,
        # which always produces a Mantle project. `generating` covers both the
        # scaffold and the agentic build below, since that is the long-running
        # phase the frontend progress should reflect.
        await push_job_status_event(job, JobStatus.generating)
        await project_generator.init_from_template(ProjectTemplateName.BASIC)

        # 2. Implement the plan via the job-mode builder agent.
        await build_from_plan(approved_revision.plan, project_generator)
        await push_job_status_event(job, JobStatus.generation_success)

        # 3. Deterministic gate: validate, then commit what passed.
        await push_job_status_event(job, JobStatus.validating)
        await asyncio.to_thread(validate_project_for_generator, project_generator)
        await push_job_status_event(job, JobStatus.validation_success)

        await project_generator.git_service.commit_changes(
            GitCommitInfo(
                author=COPILOT_COMMIT_AUTHOR,
                email=config.DEFAULT_BOT_BUILDER_EMAIL,
                message=f"Build agent from plan {plan_id}",
            )
        )
        await store.set_status(plan_id, PlanStatus.BUILT)

        try:
            if record.prompt:
                await persist_user_message_to_thread(record.prompt, thread_id=thread_id)
            await persist_copilot_message_to_thread(
                _build_plan_summary_message(approved_revision.plan),
                thread_id=thread_id,
            )
        except Exception as persist_exc:
            structlogger.warning(
                "plan_to_bot_job.persist_summary_failed",
                job_id=job.id,
                error=str(persist_exc),
            )

        await push_job_status_event(job, JobStatus.done)
        job_manager.mark_done(job)

    except ValidationError as exc:
        error_message = exc.get_error_message_with_logs()
        structlogger.debug(
            "plan_to_bot_job.validation_error", job_id=job.id, error=error_message
        )
        await push_job_status_event(
            job, JobStatus.validation_error, message=error_message
        )
        job_manager.mark_done(job, error=error_message)
        await store.set_status(plan_id, PlanStatus.FAILED)

    except Exception as exc:
        structlogger.exception(
            "plan_to_bot_job.unexpected_error", job_id=job.id, error=str(exc)
        )
        await push_job_status_event(job, JobStatus.error, message=str(exc))
        job_manager.mark_done(job, error=str(exc))
        await store.set_status(plan_id, PlanStatus.FAILED)

    finally:
        heartbeat_task.cancel()
        try:
            await heartbeat_task
        except asyncio.CancelledError:
            pass
        except Exception as exc:
            structlogger.warning(
                "plan_to_bot_job.heartbeat_task_failed", job_id=job.id, error=str(exc)
            )


async def run_template_to_bot_job(
    app: "Sanic",
    project_generator: ProjectGenerator,
    job: JobInfo,
    template_name: ProjectTemplateName,
) -> None:
    """Run the template-to-bot job in the background.

    Args:
        app: The Sanic application instance.
        project_generator: Generator of the agent's project the job operates on.
        job: The job information instance.
        template_name: The name of the template to use for bot generation.
    """
    copilot_template_prompt_job = job_manager.create_job()
    await push_job_status_event(
        job,
        JobStatus.received,
        payload={"copilot_template_prompt_job_id": copilot_template_prompt_job.id},
    )

    try:
        app.add_task(
            run_copilot_template_prompt_job(
                app, copilot_template_prompt_job, template_name
            )
        )

        await push_job_status_event(job, JobStatus.generating)
        commit_sha = await project_generator.init_from_template(template_name)
        bot_files = project_generator.get_bot_files()
        await push_job_status_event(job, JobStatus.generation_success)

        # Persist template prompt to history after template initialization
        # This ensures the project directory and .rasa folder exist
        try:
            template_prompt = copilot_template_prompts().get(template_name.value)
            if template_prompt:
                await persist_user_message_to_thread(template_prompt)
        except Exception as persist_exc:
            # Don't fail the job if persistence fails, just log it
            structlogger.error(
                "template_to_bot_job.persist_template_prompt_failed",
                job_id=job.id,
                template=template_name.value,
                error=str(persist_exc),
            )

        copilot_welcome_job = job_manager.create_job(commit_sha)
        app.add_task(
            run_copilot_welcome_message_job(
                app, project_generator, copilot_welcome_job, template_name
            )
        )

        structlogger.info(
            "bot_builder_service.template_to_bot.success",
            files_generated=list(bot_files.keys()),
            copilot_template_prompt_job_id=copilot_template_prompt_job.id,
            copilot_welcome_job_id=copilot_welcome_job.id,
        )
        await push_job_status_event(
            job=job,
            status=JobStatus.done,
            payload={"copilot_welcome_job_id": copilot_welcome_job.id},
        )
        job_manager.mark_done(job)

    except ValidationError as exc:
        # Log levels to include in the error message
        log_levels = ["error"]
        if config.VALIDATION_FAIL_ON_WARNINGS:
            log_levels.append("warning")

        structlogger.debug(
            "template_to_bot_job.validation_error",
            job_id=job.id,
            error=str(exc),
            all_validation_logs=exc.validation_logs,
            included_log_levels=log_levels,
        )
        error_message = exc.get_error_message_with_logs(log_levels=log_levels)
        await push_job_status_event(
            job, JobStatus.validation_error, message=error_message
        )
        job_manager.mark_done(job, error=error_message)

    except ProjectGenerationError as exc:
        structlogger.debug(
            "template_to_bot_job.generation_error",
            job_id=job.id,
            error=str(exc),
        )
        await push_job_status_event(job, JobStatus.generation_error, message=str(exc))
        job_manager.mark_done(job, error=str(exc))

    except Exception as exc:
        # Capture full traceback
        structlogger.exception(
            "template_to_bot_job.unexpected_error",
            job_id=job.id,
            error=str(exc),
        )
        await push_job_status_event(job, JobStatus.error, message=str(exc))
        job_manager.mark_done(job, error=str(exc))


async def run_github_to_bot_job(
    app: "Sanic",
    project_generator: ProjectGenerator,
    job: JobInfo,
    repo_url: str,
    branch: Optional[str] = None,
) -> None:
    """Run the github-to-bot job: clone a public GitHub repository and validate.

    This job clones a public GitHub repository into the agent's project folder
    and validates the cloned project files.

    Args:
        app: The Sanic application instance.
        project_generator: Generator of the agent's project the job operates on.
        job: The job information instance.
        repo_url: HTTPS URL of the public GitHub repository.
        branch: Branch to checkout (defaults to default branch).
    """
    heartbeat_task = asyncio.create_task(send_heartbeat(job))

    try:
        await push_job_status_event(job, JobStatus.received)

        structlogger.info(
            "github_to_bot_job.starting",
            job_id=job.id,
            repo_url=repo_url,
            branch=branch,
        )

        # 1. Cleanup the project folder (like template-to-bot)
        project_generator.cleanup()

        # 2. Cloning
        await push_job_status_event(job, JobStatus.cloning)

        target_path = project_generator.project_folder

        # Clone the repository
        await clone_public_repo(
            repo_url=repo_url,
            target_path=target_path,
            branch=branch,
        )

        # Ensure project info is set up (similar to template-to-bot)
        ensure_first_used(project_generator.project_folder)

        await push_job_status_event(job, JobStatus.clone_success)

        # 3. Initialize git service for the cloned repo
        # For cloned repos, init_repo() returns early since .git exists,
        # but we still need to ensure builder directories are in .gitignore
        project_generator.git_service.init_repo()
        project_generator.git_service.ensure_builder_gitignore_entries()
        commit_sha = await project_generator.git_service.get_current_commit_sha()

        # 4. Validating
        await push_job_status_event(job, JobStatus.validating)
        await asyncio.to_thread(validate_project_for_generator, project_generator)
        await push_job_status_event(job, JobStatus.validation_success)

        # 5. Create copilot welcome message job
        copilot_welcome_job = job_manager.create_job(commit_sha)
        app.add_task(
            run_copilot_welcome_message_job(app, project_generator, copilot_welcome_job)
        )

        bot_files = project_generator.get_bot_files()
        structlogger.info(
            "github_to_bot_job.success",
            job_id=job.id,
            files_loaded=list(bot_files.keys()),
            commit_sha=commit_sha,
            copilot_welcome_job_id=copilot_welcome_job.id,
        )

        await push_job_status_event(
            job=job,
            status=JobStatus.done,
            payload={"copilot_welcome_job_id": copilot_welcome_job.id},
        )
        job_manager.mark_done(job)

    except GitCloneError as exc:
        error_message = str(exc)
        structlogger.error(
            "github_to_bot_job.clone_error",
            job_id=job.id,
            error=error_message,
        )
        await push_job_status_event(job, JobStatus.clone_error, message=error_message)
        job_manager.mark_done(job, error=error_message)

    except ValidationError as exc:
        log_levels = ["error"]
        if config.VALIDATION_FAIL_ON_WARNINGS:
            log_levels.append("warning")

        structlogger.debug(
            "github_to_bot_job.validation_error",
            job_id=job.id,
            error=str(exc),
            all_validation_logs=exc.validation_logs,
            included_log_levels=log_levels,
        )
        error_message = exc.get_error_message_with_logs(log_levels=log_levels)
        await push_job_status_event(
            job, JobStatus.validation_error, message=error_message
        )
        job_manager.mark_done(job, error=error_message)

    except Exception as exc:
        error_message = str(exc)
        structlogger.exception(
            "github_to_bot_job.unexpected_error",
            job_id=job.id,
            error=error_message,
        )
        await push_job_status_event(job, JobStatus.error, message=error_message)
        job_manager.mark_done(job, error=error_message)

    finally:
        # Cancel the heartbeat task - no need to await, the event loop
        # will clean it up. Awaiting could inadvertently suppress an outer
        # cancellation, which SonarQube warns against.
        if not heartbeat_task.done():
            heartbeat_task.cancel()


async def run_replace_all_files_job(
    app: "Sanic",
    project_generator: ProjectGenerator,
    job: JobInfo,
    bot_files: Dict[str, Any],
    commit_info: GitCommitInfo,
) -> None:
    """Run the replace-all-files job in the background.

    This replaces all bot files with the provided files and deletes any files
    not included in the request (excluding .rasa/ and models/ directories).

    Args:
        app: The Sanic application instance.
        project_generator: Generator of the agent's project the job operates on.
        job: The job information instance.
        bot_files: Dictionary of file names to content for replacement.
        commit_info: Optional arguments for the commit
    """
    await push_job_status_event(job, JobStatus.received)

    commit_sha: Optional[str] = None
    try:
        commit_sha = await project_generator.replace_all_bot_files(
            bot_files, commit_info
        )
        # Validating
        await push_job_status_event(job, JobStatus.validating)
        await asyncio.to_thread(validate_project_for_generator, project_generator)
        await push_job_status_event(job, JobStatus.validation_success)

        # Send final done event with copilot training success response job ID
        copilot_training_success_job = job_manager.create_job(commit_sha=commit_sha)
        app.add_task(
            run_copilot_training_success_job(
                app, project_generator, copilot_training_success_job
            )
        )

        await push_job_status_event(
            job=job,
            status=JobStatus.done,
            payload={
                "copilot_training_success_job_id": copilot_training_success_job.id
            },
        )
        job_manager.mark_done(job)

    except GitOperationInProgressError as exc:
        error_message = str(exc)
        structlogger.debug(
            "replace_all_files_job.operation_in_progress",
            job_id=job.id,
            error=error_message,
        )
        await push_job_status_event(job, JobStatus.error, message=error_message)
        job_manager.mark_done(job, error=error_message)

    except InvalidFileContentError as exc:
        error_message = str(exc)
        structlogger.debug(
            "replace_all_files_job.invalid_file_content",
            job_id=job.id,
            error=error_message,
        )
        await push_job_status_event(job, JobStatus.error, message=error_message)
        job_manager.mark_done(job, error=error_message)

    except ValidationError as exc:
        log_levels = ["error"]
        if config.VALIDATION_FAIL_ON_WARNINGS:
            log_levels.append("warning")
        structlogger.debug(
            "replace_all_files_job.validation_error",
            job_id=job.id,
            error=str(exc),
            validation_logs=exc.validation_logs,
            included_log_levels=log_levels,
        )
        error_message = exc.get_error_message_with_logs(log_levels=log_levels)
        # Push error event and start copilot analysis job
        await push_error_and_start_copilot_analysis(
            app,
            project_generator,
            job,
            JobStatus.validation_error,
            error_message,
            bot_files,
            commit_sha,
        )

        # After error mark job as done
        job_manager.mark_done(job, error=error_message)

    except Exception as exc:
        # Capture full traceback for anything truly unexpected
        error_message = str(exc)
        structlogger.exception(
            "replace_all_files_job.unexpected_error",
            job_id=job.id,
            error=error_message,
        )

        # Push error event and start copilot analysis job
        await push_error_and_start_copilot_analysis(
            app,
            project_generator,
            job,
            JobStatus.error,
            error_message,
            bot_files,
            commit_sha,
        )

        # After error mark job as done
        job_manager.mark_done(job, error=str(exc))


async def run_copilot_training_error_analysis_job(
    app: "Sanic",
    project_generator: ProjectGenerator,
    job: JobInfo,
    training_error_message: str,
    bot_files: Dict[str, Any],
    originating_job_id: Optional[str] = None,
) -> None:
    """Run copilot training error analysis job.

    Args:
        app: The Sanic application instance.
        project_generator: Generator of the agent's project that failed.
        job: The analysis job itself.
        training_error_message: The training error log to analyze.
        bot_files: The bot files to include in the analysis.
        originating_job_id: Id of the job whose failure triggered this analysis.
            Recorded on the Copilot v2 analysis trace so a run can be joined
            back to its cause; optional, since not every caller has one.
    """
    await push_job_status_event(job, JobStatus.received)

    try:
        # Create message content blocks with log content and available files
        log_content_block = LogContent(
            type="log", content=training_error_message, context="training_error"
        )
        file_content_blocks = [
            FileContent(
                type="file",
                file_path=file_path,
                # we here omit the case where file_content is None (binary file)
                # to comply with the FileContent model schema
                file_content=file_content or "",
            )
            for file_path, file_content in bot_files.items()
        ]
        internal_request_message = InternalCopilotRequestChatMessage(
            role="internal_copilot_request",
            content=[log_content_block, *file_content_blocks],
            response_category=ResponseCategory.TRAINING_ERROR_LOG_ANALYSIS,
        )

        commit_info = None
        if job.commit_sha:
            # Get commit info
            commit_info = await project_generator.git_service.get_commit_info(
                job.commit_sha
            )

            commit_info["training_success"] = False

            # Send commit
            await push_job_status_event(
                job,
                JobStatus.copilot_analyzing,
                payload={
                    "response_category": ResponseCategory.COMMIT.value,
                    "commit": commit_info,
                    "completeness": ResponseCompleteness.COMPLETE.value,
                },
            )

        # Send original error log as part of copilot_analyzing stream
        training_error_log = TrainingErrorLog(logs=[log_content_block])
        await push_job_status_event(
            job, JobStatus.copilot_analyzing, payload=training_error_log.sse_data
        )

        from rasa.builder.copilot.pydantic_ai import training_error_analysis
        from rasa.builder.telemetry.langfuse_integration.copilot_v2_analysis_langfuse_telemetry import (  # noqa: E501
            CopilotV2AnalysisTrace,
        )

        # Root Langfuse trace for the analysis. Opened here, around the whole
        # drain, rather than inside the stream: a cancelled job unwinds the
        # consumer without closing the generator, so a context manager inside it
        # would leak the span on the commonest failure path.
        analysis_trace = CopilotV2AnalysisTrace(
            request_message=internal_request_message,
            job_id=job.id,
            commit_sha=job.commit_sha,
            originating_job_id=originating_job_id,
            project_id=config.HELLO_RASA_PROJECT_ID,
        )
        with analysis_trace.observe():
            analysis_stream = training_error_analysis.stream_training_error_analysis(
                internal_request_message,
                project_path=str(project_generator.project_folder),
            )
            analysis_text_parts: List[str] = []
            async for analysis_token in analysis_stream:
                await push_job_status_event(
                    job,
                    JobStatus.copilot_analyzing,
                    payload=analysis_token.sse_data,
                )
                analysis_trace.record_output(analysis_token)
                if isinstance(analysis_token, CopilotTextContent):
                    analysis_text_parts.append(analysis_token.content)
        analysis_text = "".join(analysis_text_parts)

        # Persist the training error analysis to the copilot thread
        await persist_copilot_message_to_thread(
            analysis_text,
            response_category=ResponseCategory.TRAINING_ERROR_LOG_ANALYSIS,
        )

        # Send success status
        await push_job_status_event(job, JobStatus.copilot_analysis_success)

        await push_job_status_event(job, JobStatus.done)
        job_manager.mark_done(job)

    except Exception as exc:
        structlogger.exception(
            "copilot_training_error_analysis_job.error",
            job_id=job.id,
            error=str(exc),
        )
        await push_job_status_event(
            job, JobStatus.copilot_analysis_error, message=str(exc)
        )
        job_manager.mark_done(job, error=str(exc))


async def run_copilot_welcome_message_job(
    app: "Sanic",
    project_generator: ProjectGenerator,
    job: JobInfo,
    template_name: Optional[ProjectTemplateName] = None,
) -> None:
    """Run the welcome message job in the background.

    This job sends a welcome message to the user after successful bot creation.
    For template-based bots, it sends a predefined message.
    For prompt-based bots, it can be extended to stream generated messages.

    Args:
        app: The Sanic application instance.
        project_generator: Generator of the agent's project the job operates on.
        job: The job information instance.
        template_name: The template name for template-based bots, None for prompt-based.
    """
    try:
        # Load welcome messages from YAML
        welcome_messages = copilot_welcome_messages()

        # Get the appropriate welcome message
        if template_name:
            welcome_message = welcome_messages.get(
                template_name.value,
                welcome_messages.get(PROMPT_TO_BOT_KEY),
            )
        else:
            welcome_message = await project_generator.generate_welcome_message(
                default_welcome_message=welcome_messages.get(PROMPT_TO_BOT_KEY),
                template_welcome_message=welcome_messages.get(
                    PROMPT_TO_BOT_TEMPLATE_KEY
                ),
            )

        commit_info = None
        if job.commit_sha:
            # Get commit info
            commit_info = await project_generator.git_service.get_commit_info(
                job.commit_sha
            )

            commit_info["training_success"] = True

            # Send commit
            await push_job_status_event(
                job,
                JobStatus.copilot_welcome_message,
                payload={
                    "response_category": ResponseCategory.COMMIT.value,
                    "commit": commit_info,
                    "completeness": ResponseCompleteness.COMPLETE.value,
                },
            )

        # Send the welcome message as a single event
        await push_job_status_event(
            job,
            JobStatus.copilot_welcome_message,
            payload={
                "content": welcome_message,
                "response_category": ResponseCategory.COPILOT.value,
                "completeness": ResponseCompleteness.COMPLETE.value,
            },
        )

        # Persist the welcome message to conversation history
        await persist_copilot_message_to_thread(welcome_message)

        # Mark job as done
        await push_job_status_event(job, JobStatus.done)
        job_manager.mark_done(job)

        structlogger.info(
            "copilot_welcome_message_job.success",
            job_id=job.id,
            template=template_name.value if template_name else PROMPT_TO_BOT_KEY,
        )

    except Exception as exc:
        structlogger.exception(
            "welcome_message_job.error",
            job_id=job.id,
            error=str(exc),
        )
        await push_job_status_event(job, JobStatus.error, message=str(exc))
        job_manager.mark_done(job, error=str(exc))


